package com.example.modernnotes.data.note.local.entities

import androidx.room.Entity
import androidx.room.PrimaryKey

@Entity(tableName = "notes")
data class NoteEntity(
    // TODO Remove the "autogenerated" and the default 0 value when Retrofit implementation it's created
    @PrimaryKey(autoGenerate = true)
    val id: Int = 0,
    val title: String,
    val content: String,
    val createdAt: Long
)